val RequireOrdersRead = createRouteScopedPlugin("RequireOrdersRead") {
    onCallValidators { call ->
        val principal = call.principal<JWTPrincipal>()
        val scopes = principal?.payload?.getClaim("scope")
            ?.asList(String::class.java).orEmpty()
        if ("orders:read" !in scopes) {
            call.respond(HttpStatusCode.Forbidden)
            finish()                                  // enforcement stops the handler
        }
    }
}

install(Authentication) { jwt("auth-jwt") { verifier(jwtVerifier) } }

routing {
    authenticate("auth-jwt") {                    // authentication gate
        install(RequireOrdersRead)                    // centralized decision + PEP
        get("/orders") { call.respond(orderService.list()) }
    }
}
